/* Private feedback drafts stay in memory and are cleared when accounts change. */
(function(root){
 'use strict';
 const kinds={bug:'Report a bug',suggestion:'Suggest an improvement',question:'Ask a question'},areas={signin:'Sign-in / Signup',import:'Importing a list',builder:'Creating / Editing a list',practice:'Practice quizzes',guide:'Game guide / Learn to play',rules:'Rules / Workshop',account:'My Account',printing:'Printing / Saving a guide',other:'Something else'},statuses={new:'New','in-progress':'In progress',resolved:'Resolved'};
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const empty=()=>({kind:'bug',area:'other',title:'',description:'',steps:'',expected:'',frequency:'unsure',impact:'minor',contact_email:'',attachment_url:'',includeDiagnostics:true});
 function validate(data){
  if(!Object.hasOwn(kinds,data.kind)||!Object.hasOwn(areas,data.area))throw Error('Choose the feedback type and app area.');
  for(const [field,max,label] of [['title',160,'summary'],['description',5000,'details']])if(typeof data[field]!=='string'||!data[field].trim()||data[field].length>max)throw Error('Enter '+label+' (up to '+max+' characters).');
  for(const [field,max] of [['steps',5000],['expected',3000],['contact_email',254],['attachment_url',2000]])if(typeof data[field]!=='string'||data[field].length>max)throw Error('Review the '+field.replaceAll('_',' ')+' field.');
  if(!['always','sometimes','once','unsure'].includes(data.frequency)||!['blocked','difficult','minor'].includes(data.impact))throw Error('Choose valid frequency and impact options.');
  if(data.contact_email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.contact_email))throw Error('Enter a valid contact email or leave it blank.');
  if(data.attachment_url&&!/^https?:\/\/\S+$/i.test(data.attachment_url))throw Error('Use an https:// or http:// screenshot link.');
  return data;
 }
 if(typeof module!=='undefined'&&module.exports){module.exports={kinds,areas,statuses,validate};return;}
 let service=null,epoch=0,dialog=null,draft=empty(),context={},busy=false,error='',receipt=null,id=null,signature=null;
 let inbox=[],inboxFilter='open',inboxOpen=false,inboxBusy=false,inboxLoading=false,inboxError='',inboxAgain=false;
 const uid=()=>root.crypto.randomUUID();
 function diagnostics(){const app=root.getWarPlannerFeedbackContext?.()||{},result={version:document.querySelector('meta[name="application-version"]')?.content||'0.28.5',browser:String(root.navigator?.userAgent||'').slice(0,600),language:root.navigator?.language||'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'',viewport:root.innerWidth+'×'+root.innerHeight};for(const key of ['page','guideMode','phase','turn','faction'])if(typeof app[key]==='string')result[key]=app[key].slice(0,180);return result;}
 const options=(values,current)=>Object.entries(values).map(([value,label])=>`<option value="${e(value)}" ${value===current?'selected':''}>${e(label)}</option>`).join('');
 const field=(name,label,max,rows=3,required=false)=>`<label for="feedback-${name}">${label}</label><textarea id="feedback-${name}" name="${name}" rows="${rows}" maxlength="${max}" ${required?'required':''}>${e(draft[name])}</textarea>`;
 function draw(){
  const bug=draft.kind==='bug';
  dialog.innerHTML=`<header><h2 id="feedback-title">Send feedback</h2><button type="button" class="icon-button" data-feedback-action="close" aria-label="Close feedback">×</button></header>${receipt?`<section class="feedback-receipt" role="status"><h3>Thank you — your feedback was sent.</h3><p>Reference: ${e(receipt.slice(-8))}</p><p>It’s in the admin inbox for review.${draft.contact_email?' We can use the email you provided if we need more details.':''}</p><button type="button" class="outline" data-feedback-action="another">Send another</button></section>`:`<p>Tell us what went wrong, what could be better, or where you need help. Fields marked * are required.</p>${!service?.submitFeedback?'<p class="feedback-error" role="status">Sign in to send feedback.</p>':''}<form data-feedback-form><fieldset ${busy||!service?.submitFeedback?'disabled':''}><div class="feedback-columns"><label>Feedback type<select name="kind">${options(kinds,draft.kind)}</select></label><label>App area<select name="area">${options(areas,draft.area)}</select></label></div><label for="feedback-summary">Short summary *</label><input id="feedback-summary" name="title" value="${e(draft.title)}" maxlength="160" required placeholder="For example: the guide stops responding after a swipe">${field('description',bug?'What happened? *':draft.kind==='suggestion'?'What would you like to improve? *':'What do you need help with? *',5000,4,true)}${bug?`${field('steps','Steps to reproduce (if known)',5000,3)}${field('expected','What did you expect to happen?',3000,2)}<div class="feedback-columns"><label>How often does it happen?<select name="frequency">${options({unsure:'Not sure',always:'Every time',sometimes:'Sometimes',once:'Only once'},draft.frequency)}</select></label><label>How much does this affect you?<select name="impact">${options({minor:'Minor inconvenience',difficult:'Makes the feature hard to use',blocked:'Stops me using the feature'},draft.impact)}</select></label></div>`:''}<label for="feedback-attachment">Screenshot or recording link (optional)</label><input id="feedback-attachment" name="attachment_url" type="url" maxlength="2000" value="${e(draft.attachment_url)}" placeholder="https://…"><p class="feedback-help">Use a shareable link if you have one. Don’t include passwords or other private information.</p><label for="feedback-contact">Contact email (optional)</label><input id="feedback-contact" name="contact_email" type="email" autocomplete="email" maxlength="254" value="${e(draft.contact_email)}"><p class="feedback-help">Only needed if you’d like us to contact you with questions about this report.</p><label class="feedback-diagnostics"><input type="checkbox" name="includeDiagnostics" ${draft.includeDiagnostics?'checked':''}>Include technical details to help diagnose the issue</label><details class="feedback-context"><summary>Review technical details</summary><pre>${e(JSON.stringify(context,null,2))}</pre><p class="feedback-help">Only included when the checkbox above is selected. We don’t attach army exports, passwords, or full page URLs.</p></details><p class="feedback-error" role="alert">${e(error)}</p><button type="submit" class="primary">${busy?'Sending…':'Send feedback'}</button></fieldset></form>`}`;
 }
 function record(form){const data=new FormData(form);for(const key of Object.keys(empty())){if(key==='includeDiagnostics')draft[key]=data.has(key);else if(data.has(key))draft[key]=String(data.get(key));}}
 function open(){if(!dialog){dialog=document.createElement('dialog');dialog.className='feedback-dialog';dialog.setAttribute('aria-labelledby','feedback-title');document.body.append(dialog);}context=diagnostics();if(!draft.title&&!draft.description)draft.area=({army:'builder',practice:'practice',guide:'guide',account:'account',admin:'rules'})[context.page]||'other';draw();if(!dialog.open)dialog.showModal();dialog.querySelector('#feedback-summary')?.focus();}
 async function send(form){
  if(!service?.submitFeedback||busy)return;record(form);const current=service,session=epoch;
  try{
   const payload=validate(Object.fromEntries(['kind','area','title','description','steps','expected','frequency','impact','contact_email','attachment_url'].map(key=>[key,String(draft[key]).trim()])));if(payload.kind!=='bug'){payload.steps='';payload.expected='';payload.frequency='unsure';payload.impact='minor';}payload.context=draft.includeDiagnostics?{...context}:{};
   const next=JSON.stringify(payload);if(signature!==next){id=uid();signature=next;}payload.id=id;busy=true;error='';draw();
   const saved=await current.submitFeedback(payload);if(epoch!==session)return;receipt=saved.id;busy=false;draw();dialog.querySelector('.feedback-receipt')?.scrollIntoView({block:'nearest'});if(current.isAdmin)void reloadInbox();
  }catch(failure){if(epoch!==session)return;busy=false;error=failure.message||'Could not send feedback. Your draft is still here. Please retry.';draw();dialog.querySelector('[role="alert"]')?.scrollIntoView({block:'nearest'});}
 }
 function inboxHTML(){if(!service?.isAdmin)return '';return `<details class="feedback-inbox" ${inboxOpen?'open':''} data-feedback-inbox><summary>Bug reports & feedback (${inbox.length}${inbox.length===100?'+':''})</summary><div class="feedback-inbox-controls"><label>Show<select data-feedback-filter>${options({open:'New / In progress',resolved:'Resolved',all:'All'},inboxFilter)}</select></label><button type="button" class="outline" data-feedback-action="refresh" ${inboxLoading||inboxBusy?'disabled':''}>Refresh feedback</button></div><p role="status" class="${inboxError?'feedback-error':''}">${e(inboxError||(inboxLoading?'Loading feedback…':''))}</p>${inbox.map(report=>`<article class="feedback-inbox-card"><h3>${e(report.title)}</h3><p class="feedback-help">${e(kinds[report.kind]||report.kind)} · ${e(areas[report.area]||report.area)} · ${e(statuses[report.status])} · ${e(new Date(report.created_at).toLocaleString())}</p><p>${e(report.description)}</p>${report.steps?`<h4>Steps to reproduce</h4><p>${e(report.steps)}</p>`:''}${report.expected?`<h4>Expected behaviour</h4><p>${e(report.expected)}</p>`:''}${report.kind==='bug'?`<p class="feedback-help">Frequency: ${e(report.frequency)} · Impact: ${e(report.impact)}</p>`:''}${report.contact_email?`<p>Contact: ${e(report.contact_email)}</p>`:''}${/^https?:\/\/\S+$/i.test(report.attachment_url||'')?`<p><a href="${e(report.attachment_url)}" target="_blank" rel="noopener noreferrer">Screenshot / recording ↗</a></p>`:''}<details><summary>Technical details & reference</summary><p>Reference: ${e(report.id)}</p><pre>${e(JSON.stringify(report.context||{},null,2))}</pre></details><div class="button-row">${Object.entries(statuses).filter(([status])=>status!==report.status).map(([status,label])=>`<button type="button" class="outline" data-feedback-status="${status}" data-feedback-id="${e(report.id)}" ${inboxBusy?'disabled':''}>Mark ${label}</button>`).join('')}</div></article>`).join('')||(!inboxLoading?'<p>No feedback in this view.</p>':'')}<p class="feedback-help">Showing up to 100 recent submissions.</p></details>`;}
 function updateInbox(){const box=document.querySelector('#user-feedback-inbox');if(box)box.innerHTML=inboxHTML();}
 async function reloadInbox(){
  if(!service?.isAdmin||!service.listFeedback)return;if(inboxLoading||inboxBusy){inboxAgain=true;return;}
  const current=service,session=epoch,filter=inboxFilter;inboxLoading=true;inboxError='';updateInbox();
  try{const rows=await current.listFeedback(filter);if(epoch===session&&filter===inboxFilter)inbox=rows;}
  catch(failure){if(epoch===session&&filter===inboxFilter)inboxError=failure.message||'Could not load feedback.';}
  finally{if(epoch===session){inboxLoading=false;const again=inboxAgain||filter!==inboxFilter;inboxAgain=false;if(again)void reloadInbox();else updateInbox();}}
 }
 document.addEventListener('input',event=>{const form=event.target.closest?.('[data-feedback-form]');if(form&&!busy)record(form);});
 document.addEventListener('change',event=>{const form=event.target.closest?.('[data-feedback-form]');if(form&&!busy){record(form);if(event.target.name==='kind'){draw();dialog.querySelector('[name=kind]')?.focus();}}if(event.target.matches?.('[data-feedback-filter]')){inboxFilter=event.target.value;inbox=[];void reloadInbox();}});
 document.addEventListener('submit',event=>{if(event.target.matches?.('[data-feedback-form]')){event.preventDefault();void send(event.target);}});
 document.addEventListener('toggle',event=>{if(event.target.matches?.('[data-feedback-inbox]'))inboxOpen=event.target.open;},true);
 document.addEventListener('click',async event=>{
  if(event.target.closest?.('[data-open-feedback]')){open();return;}const action=event.target.closest?.('[data-feedback-action]')?.dataset.feedbackAction;
  if(action==='close')dialog?.close();if(action==='another'){draft=empty();receipt=null;signature=null;error='';draw();}if(action==='refresh')void reloadInbox();
  const button=event.target.closest?.('[data-feedback-status]');if(!button||!service?.isAdmin||inboxBusy||inboxLoading)return;const current=service,session=epoch;inboxBusy=true;inboxError='';updateInbox();try{await current.setFeedbackStatus(button.dataset.feedbackId,button.dataset.feedbackStatus);}catch(failure){if(epoch===session)inboxError=failure.message||'Could not update feedback.';}finally{if(epoch===session){inboxBusy=false;if(inboxError)updateInbox();else void reloadInbox();}}
 });
 root.WarPlannerFeedback={open,inboxHTML,setService(next){if(service===next)return;epoch++;service=next;dialog?.close();if(dialog)dialog.innerHTML='';draft=empty();context={};receipt=null;signature=null;error='';id=null;busy=false;inbox=[];inboxLoading=false;inboxBusy=false;inboxError='';inboxAgain=false;inboxOpen=false;inboxFilter='open';updateInbox();if(next?.isAdmin)void reloadInbox();},reloadInbox};
})(typeof window!=='undefined'?window:globalThis);
